    "scene": "3月・数字で会社を語る",
    "story": "一年かけて整えた帳簿を基に、主人公は残高と利益を根拠付きで説明する。",
    "question": "社長から『現金はいくら残り、今月はいくらもうかったのか』と尋ねられた。資料の取引を仕訳の向きで整理し、二つの金額を答えなさい。",
